import { Octokit } from '@octokit/rest';
import { OrchestratorResult, Severity } from './types';

function getOctokit(): Octokit {
  const token = process.env.GITHUB_TOKEN;
  if (!token) throw new Error('GITHUB_TOKEN env var is required');
  return new Octokit({ auth: token });
}

const SEVERITY_EMOJI: Record<Severity, string> = {
  CRITICAL: '🔴',
  HIGH: '🟠',
  MEDIUM: '🟡',
  LOW: '🔵',
};

const VERDICT_EMOJI: Record<OrchestratorResult['verdict'], string> = {
  pass: '✅',
  'comment-only': '⚠️',
  fix: '🔧',
};

const VERDICT_LABEL: Record<OrchestratorResult['verdict'], string> = {
  pass: 'PASSED',
  'comment-only': 'NEEDS ATTENTION',
  fix: 'AUTO-FIX APPLIED',
};

/**
 * Posts a formatted review comment on the PR.
 */
export async function postReviewComment(
  owner: string,
  repo: string,
  prNumber: number,
  result: OrchestratorResult,
): Promise<void> {
  const octokit = getOctokit();
  const body = buildCommentBody(result);

  await octokit.rest.issues.createComment({
    owner,
    repo,
    issue_number: prNumber,
    body,
  });

  console.log(`[pr-commenter] Posted review comment on PR #${prNumber}`);
}

function buildCommentBody(result: OrchestratorResult): string {
  const lines: string[] = [
    `## ${VERDICT_EMOJI[result.verdict]} PR Review — ${VERDICT_LABEL[result.verdict]}`,
    '',
    `> ${result.summary}`,
    '',
  ];

  // --- Security ---
  const { security } = result.agentFindings;
  if (security.issues.length > 0) {
    lines.push(`### 🔒 Security Analysis`);
    lines.push(`**Overall Risk:** \`${security.overallRisk}\``);
    lines.push('');
    for (const issue of security.issues) {
      lines.push(
        `- ${SEVERITY_EMOJI[issue.severity]} **[${issue.severity}]** \`${issue.location}\` — ${issue.description}`,
      );
      lines.push(`  > **Recommendation:** ${issue.recommendation}`);
    }
    lines.push('');
  }

  // --- Quality ---
  const { quality } = result.agentFindings;
  if (quality.issues.length > 0) {
    lines.push(`### 📐 Code Quality Analysis`);
    lines.push(`**Quality Score:** ${quality.qualityScore}/10`);
    lines.push('');
    for (const issue of quality.issues) {
      lines.push(
        `- ${SEVERITY_EMOJI[issue.severity]} **[${issue.severity}]** \`${issue.location}\` — ${issue.description}`,
      );
      lines.push(`  > **Suggestion:** ${issue.suggestion}`);
    }
    lines.push('');
  }

  // --- Logic ---
  const { logic } = result.agentFindings;
  if (logic.issues.length > 0) {
    lines.push(`### 🧠 Logic & Correctness Analysis`);
    lines.push(`**Confidence:** ${Math.round(logic.confidence * 100)}%`);
    lines.push('');
    for (const issue of logic.issues) {
      lines.push(
        `- ${SEVERITY_EMOJI[issue.severity]} **[${issue.severity}]** \`${issue.location}\` — ${issue.description}`,
      );
      lines.push(`  > **Fix:** ${issue.fix}`);
    }
    lines.push('');
  }

  // --- Tests ---
  const { testGen } = result.agentFindings;
  if (testGen.missingTests.length > 0) {
    lines.push(`### 🧪 Missing Test Coverage`);
    lines.push('');
    for (const test of testGen.missingTests) {
      lines.push(`**${test.description}** → \`${test.filename}\``);
      lines.push('');
      lines.push('```');
      lines.push(test.testCode);
      lines.push('```');
      lines.push('');
    }
  }

  // --- Fix notice ---
  if (result.verdict === 'fix' && result.fixedFiles && result.fixedFiles.length > 0) {
    lines.push(`### 🔧 Auto-Fix Applied`);
    lines.push('');
    lines.push(
      'The following files were automatically remediated and submitted as a companion fix PR:',
    );
    lines.push('');
    for (const file of result.fixedFiles) {
      lines.push(`- \`${file.filename}\`: ${file.changesSummary}`);
    }
    lines.push('');
  }

  lines.push('---');
  lines.push('*🤖 Generated by [PR Review Pipeline](https://github.com)*');

  return lines.join('\n');
}
